export async function queueParcel(parcel: string, tenant: string) {
  const response = await fetch("/v3/parcels", {
    method: "POST", headers: { "X-Parcel-Tenant": tenant }, body: JSON.stringify({ parcel }),
  });
  return response.json();
}

parcel-publisher.java/Parcels.java:
record ParcelQueued(String parcel, String tenant) {}
interface EventPublisher { void publish(String topic, String key, ParcelQueued event); }
final class Parcels {
  private final EventPublisher publisher;
  Parcels(EventPublisher publisher) { this.publisher = publisher; }
  void queue(String parcel, String tenant) {
    var event = new ParcelQueued(parcel, tenant);
    publisher.publish("parcel.queued.v3", tenant, event);
  }
}

parcel-index.java/QueueReader.java:
record ParcelQueued(String parcel, String tenant) {}
record ParcelKey(String tenant, String parcel) {}
interface MongoCollection { void replaceOne(ParcelKey selector, ParcelQueued document, boolean upsert); }
interface KafkaSubscriber { void subscribe(String topic, String group, QueueReader handler); }
final class QueueReader {
  private final MongoCollection collection;
  QueueReader(MongoCollection collection) { this.collection = collection; }
  void start(KafkaSubscriber subscriber, String group) { subscriber.subscribe("parcel.queued.v3", group, this); }
  void onMessage(ParcelQueued event) {
    var selector = new ParcelKey(event.tenant(), event.parcel());
    collection.replaceOne(selector, event, true);
  }
}
